import{_ as e,o,c as d,a3 as a}from"./chunks/framework._FWOmmqu.js";const p=JSON.parse('{"title":"AI Credit Note triage tools (ai 1.15.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"AI Credit Note triage tools (ai 1.15.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/ai-credit-note-triage-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"AI Credit Note triage tools (ai 1.15.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/ai-credit-note-triage-production-readiness"}]]},"headers":[],"relativePath":"deployment/ai-credit-note-triage-production-readiness.md","filePath":"deployment/ai-credit-note-triage-production-readiness.md","lastUpdated":1789681713000}'),r={name:"deployment/ai-credit-note-triage-production-readiness.md"};function s(i,t,n,c,g,l){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="ai-credit-note-triage-tools-ai-1-15-0-—-production-readiness-audit" tabindex="-1">AI Credit Note triage tools (ai 1.15.0) — Production Readiness Audit <a class="header-anchor" href="#ai-credit-note-triage-tools-ai-1-15-0-—-production-readiness-audit" aria-label="Permalink to &quot;AI Credit Note triage tools (ai 1.15.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-16</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> — Backend + Docs; <strong>no SPA/Mobile code</strong></td></tr><tr><td><strong>Scope</strong></td><td>Ask EloSync Credit Note tools: <code>get_credit_note</code>, confirmed writes <code>update_credit_note_status</code> / <code>assign_credit_note</code> / <code>add_credit_note_note</code>; catalog <strong>ai 1.14.0 → 1.15.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="./ai">AI deployment</a> · <a href="./ai-quotation-triage-production-readiness">AI Quotation triage</a> · <a href="./ai-payment-triage-production-readiness">AI Payment triage</a> · <a href="/developer-guide/ai-tools">AI tools</a> · <a href="/api/tenant-v1-ai">Tenant AI API</a> · <a href="/user-guide/ai-assistant">User guide</a> · <a href="/user-guide/credit-notes">Credit Notes</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Additive AI tools depth on the existing <code>AIGateway</code> + <code>AIToolRegistry</code> + <code>PendingAiActionService</code> path. Reads: fetch one credit note (UUID; payload includes number, title, amounts, linked invoice, assignee, latest note). Writes: three low-risk tools that propose pending actions; mutations run only after <code>POST /ai/actions/{id}/confirm</code>. Status confirm calls <strong><code>CustomerCreditNoteService::issue()</code></strong> for Issued, <strong><code>apply()</code></strong> for Applied, <strong><code>void()</code></strong> for Void, and <strong><code>refund()</code></strong> for Refunded (Payment-style dedicated actions — not a generic <code>changeStatus</code>). Draft as a target is rejected. Status auth mirrors issue/apply/void/refund policies. Registry visibility for status uses <code>AiToolAnyOfPermissions</code> (<code>credit-notes.update</code> | <code>issue</code> | <code>apply</code> | <code>void</code> | <code>refund</code>). Assign uses <code>credit-notes.assign</code> + <code>EligibleCreditNoteAssignee</code> at propose <strong>and</strong> confirm. Notes are text-only with confirm-time <code>max:5000</code>. No new Spatie permissions, no Credit Notes catalog bump, no Frontend/Mobile changes.</p><p><strong>Go / No-Go:</strong> <strong>Go</strong>. Cutover: migrate-only catalog bump to <strong>1.15.0</strong>, entitle <code>ai</code> + <code>credit-notes</code> (requires Invoices), staging smoke propose→confirm.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze (no parallel AI stack)</td><td><strong>Pass</strong></td></tr><tr><td>UUID credit note lookup; soft-deleted excluded</td><td><strong>Pass</strong></td></tr><tr><td>Status propose/confirm: Issued→<code>issue()</code>, Applied→<code>apply()</code>, Void→<code>void()</code>, Refunded→<code>refund()</code>; Draft target rejected</td><td><strong>Pass</strong></td></tr><tr><td>Status tool visible with any of update/issue/apply/void/refund</td><td><strong>Pass</strong></td></tr><tr><td>Assign gated by <code>credit-notes.assign</code> + <code>EligibleCreditNoteAssignee</code> (propose <strong>and</strong> confirm)</td><td><strong>Pass</strong></td></tr><tr><td>Note gated by <code>credit-notes.update</code> + policy <code>update</code> + body max 5000 on confirm</td><td><strong>Pass</strong></td></tr><tr><td>Propose does not mutate</td><td><strong>Pass</strong></td></tr><tr><td>Get payload exposes invoice link + <code>assigned_to</code> / <code>assignee_name</code></td><td><strong>Pass</strong></td></tr><tr><td>Catalog migrate-only <code>ai</code> <strong>1.15.0</strong> + CatalogSeeder sync</td><td><strong>Pass</strong></td></tr><tr><td>Docs (tools, API, user tip, Credit Notes cross-links, overview, ops, roadmap, changelog, upgrade, VitePress)</td><td><strong>Pass</strong></td></tr><tr><td>Pest write confirmation + registry</td><td><strong>Pass</strong></td></tr><tr><td>Playwright AI e2e</td><td><strong>N/A</strong> — no SPA surface change</td></tr></tbody></table><hr><h2 id="locked-decision-matrix" tabindex="-1">Locked-decision matrix <a class="header-anchor" href="#locked-decision-matrix" aria-label="Permalink to &quot;Locked-decision matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision</th><th>Backend</th><th>Frontend</th><th>Mobile</th><th>Docs</th></tr></thead><tbody><tr><td>Read tool: get one credit note</td><td>Pass</td><td>—</td><td>—</td><td>Pass</td></tr><tr><td>Confirmed writes via existing pending actions</td><td>Pass</td><td>Pass (generic UI)</td><td>Pass (generic UI)</td><td>Pass</td></tr><tr><td>Status via dedicated <code>issue()</code> / <code>apply()</code> / <code>void()</code> / <code>refund()</code> (not draft)</td><td>Pass</td><td>—</td><td>—</td><td>Pass</td></tr><tr><td><code>AiToolAnyOfPermissions</code> for status visibility</td><td>Pass</td><td>—</td><td>—</td><td>Pass</td></tr><tr><td>Catalog MINOR <strong>ai 1.15.0</strong> only (not credit-notes)</td><td>Pass</td><td>—</td><td>—</td><td>Pass</td></tr></tbody></table><hr><h2 id="authz-map-http-↔-ai" tabindex="-1">Authz map (HTTP ↔ AI) <a class="header-anchor" href="#authz-map-http-↔-ai" aria-label="Permalink to &quot;Authz map (HTTP ↔ AI)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>HTTP</th><th>AI tool / confirm</th></tr></thead><tbody><tr><td>Get one</td><td><code>view</code> (assignee-scoped unless <code>assign</code> / superadmin)</td><td><code>get_credit_note</code></td></tr><tr><td>Issue</td><td><code>issue</code></td><td><code>update_credit_note_status</code> → <code>issue()</code></td></tr><tr><td>Apply</td><td><code>apply</code></td><td><code>update_credit_note_status</code> → <code>apply()</code></td></tr><tr><td>Void</td><td><code>void</code></td><td><code>update_credit_note_status</code> → <code>void()</code></td></tr><tr><td>Refund</td><td><code>refund</code></td><td><code>update_credit_note_status</code> → <code>refund()</code></td></tr><tr><td>Assign / unassign</td><td><code>assign</code></td><td><code>assign_credit_note</code> + <code>EligibleCreditNoteAssignee</code> at propose <strong>and</strong> confirm</td></tr><tr><td>Note (text)</td><td><code>update</code></td><td><code>add_credit_note_note</code> + confirm <code>max:5000</code></td></tr></tbody></table><hr><h2 id="upgrade-staging-smoke" tabindex="-1">Upgrade &amp; staging smoke <a class="header-anchor" href="#upgrade-staging-smoke" aria-label="Permalink to &quot;Upgrade &amp; staging smoke&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code> — catalog <code>ai</code> → <strong>1.15.0</strong> (do <strong>not</strong> <code>db:seed</code>).</li><li>Entitle <code>ai</code> + <code>credit-notes</code> (Invoices required).</li><li>Smoke: Ask EloSync fetch credit note → propose status/assign/note → Confirm; Issued needs <code>issue</code>; Draft target fails.</li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Roll back the catalog bump migration (<code>down</code> → <strong>1.14.0</strong>). Tools remain in code but version claim reverts; no schema change.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><p>Unchanged from AI platform readiness (Nightwatch / logs on AI gateway + pending action confirm failures).</p>',20)])])}const m=e(r,[["render",s]]);export{p as __pageData,m as default};
